import{_ as a,C as i,o as t,c as n,j as r,a as o,b as c,w as d,E as l,a3 as u,a2 as h}from"./chunks/framework.C8nVztS1.js";const v=JSON.parse('{"title":"How it works","description":"Recipe lifecycle, artifacts, identity cache, and import map.","frontmatter":{"title":"How it works","description":"Recipe lifecycle, artifacts, identity cache, and import map.","outline":"deep"},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md","lastUpdated":1793338095000}'),p={name:"guide/how-it-works.md"};function g(f,e,w,b,m,y){const s=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=r("h1",{id:"how-it-works",tabindex:"-1"},[o("How it works "),r("a",{class:"header-anchor",href:"#how-it-works","aria-label":'Permalink to "How it works"'},"​")],-1)),(t(),c(u,null,{default:d(()=>[l(s,{id:"mermaid-3",class:"mermaid",graph:"flowchart%20LR%0A%20%20recipes%5Brecipes.ts%5D%20--%3E%20prepare%5Bprepare%20optional%5D%0A%20%20prepare%20--%3E%20artifacts%5B.untestutils%2Fbuilds%5D%0A%20%20artifacts%20--%3E%20start%5Bstart%5D%0A%20%20start%20--%3E%20running%5BRunning%20url%20%2F%20dir%5D%0A%20%20running%20--%3E%20harness%5BuseHarness%5D%0A%20%20harness%20--%3E%20specs%5BVitest%20%2F%20Playwright%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=h('<h2 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Recipe</strong></td><td>Optional <code>prepare</code>, required <code>start</code>, optional <code>ready</code> / <code>share</code> / <code>hashInputs</code></td></tr><tr><td><strong>Driver</strong></td><td>Factory that returns a Recipe (<code>staticDir</code>, <code>nuxt</code>, <code>host</code>, …)</td></tr><tr><td><strong>Running</strong></td><td><code>{ kind: &#39;url&#39;, url, stop }</code> and/or <code>{ kind: &#39;dir&#39;, dir }</code></td></tr><tr><td><strong>HarnessHandle</strong></td><td><code>url?</code>, <code>dir?</code>, <code>$fetch</code>, <code>files.*</code></td></tr><tr><td><strong>Identity</strong></td><td>Hash of recipe id + inputs → cache key under <code>.untestutils</code></td></tr></tbody></table><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><ol><li><strong>Register</strong> — <code>defineRecipes({ … }, import.meta.url)</code></li><li><strong>Prepare</strong> (optional) — build into an artifact dir; skipped when cache is warm</li><li><strong>Start</strong> — local server, dir, or remote URL</li><li><strong>Ready</strong> — HTTP (or custom) gate</li><li><strong>Teardown</strong> — stop processes; clear registry</li></ol><p>Local servers bind to <strong><code>127.0.0.1</code></strong>.</p><h3 id="run-dev-is-not-the-fast-path" tabindex="-1"><code>run: &#39;dev&#39;</code> is not the fast path <a class="header-anchor" href="#run-dev-is-not-the-fast-path" aria-label="Permalink to &quot;`run: &#39;dev&#39;` is not the fast path&quot;">​</a></h3><p>Framework drivers default to a <strong>built</strong> mode (<code>nuxt</code> → <code>server</code>, Vite → <code>preview</code>, …) so prepare can be shared. <code>run: &#39;dev&#39;</code> skips prepare, sets <code>share: &#39;never&#39;</code>, and exists only for niche HMR assertions. See <a href="/untestutils/guide/drivers#run-modes-nuxt">Drivers</a>.</p><h2 id="shared-prepare-speed" tabindex="-1">Shared prepare (speed) <a class="header-anchor" href="#shared-prepare-speed" aria-label="Permalink to &quot;Shared prepare (speed)&quot;">​</a></h2><p>Prepare outputs live under <code>.untestutils/builds</code>, keyed by identity. Parallel workers take a file lock so they do not corrupt the same build; a waiter keeps waiting while the holder&#39;s heartbeat is fresh (long builds are fine) and only fails — naming the holder pid — once the heartbeat stops. Running URLs are registered for Playwright/Vitest (<code>UNTESTUTILS_HOST_&lt;ID&gt;</code>).</p><p>Per-run state — registry and <code>locks/</code> — lives under the artifacts root&#39;s <code>run/</code> directory (default <code>.untestutils/run/</code>), apart from <code>builds/</code>. Each test run (vitest/playwright plugin) gets its own registry in <code>run/runs/&lt;runId&gt;/</code> (<code>targets.json</code> + <code>owner.json</code>, the run&#39;s main pid). So two <code>vitest run</code>s in one checkout never stop each other&#39;s servers. Each run starts its own servers from the shared <code>builds/</code> cache, and a cold build waits on the other run&#39;s build lock. Of other runs&#39; servers, global setup stops only those whose run&#39;s owner process is gone (a run dir with no <code>owner.json</code> counts after 60 s). It also stops everything in the shared no-run-id registry (<code>run/targets.json</code>, used by code that calls core without a plugin) and the pre-0.8 <code>&lt;root&gt;/targets.json</code>; neither has an owner check. A nested runner (a <code>vitest run</code> spawned by a test) gets its own run id. Teardown stops its own run&#39;s servers and removes the run dir. Registry entries record the server&#39;s OS start time when available (Linux <code>/proc</code>, macOS <code>ps</code>); teardown uses it to skip a pid the OS recycled after a crash. On Windows (or without <code>ps</code>) it falls back to a plain pid check. A server start that hits <code>EADDRINUSE</code> is retried on a fresh port.</p><p>Global teardown prunes <code>builds/</code>: per recipe id it keeps the 2 most recently used identities plus everything the run used, and never removes a build whose lock is held (<code>gc</code> option / <code>UNTESTUTILS_GC</code>).</p><table tabindex="0"><thead><tr><th>Env</th><th>Effect</th></tr></thead><tbody><tr><td><code>UNTESTUTILS_SHARE=0</code></td><td>Disable sharing</td></tr><tr><td><code>UNTESTUTILS_DEBUG=1</code></td><td>Verbose logs</td></tr><tr><td><code>UNTESTUTILS_ARTIFACTS_DIR</code></td><td>Custom artifacts root</td></tr><tr><td><code>UNTESTUTILS_SESSION</code></td><td>Playwright session namespace (see <a href="/untestutils/guide/playwright">Playwright</a>)</td></tr><tr><td><code>UNTESTUTILS_PREWARM_CONCURRENCY</code></td><td>Parallel prewarm limit</td></tr><tr><td><code>UNTESTUTILS_GC</code></td><td><code>0</code> disables build GC, a number sets keep-per-recipe</td></tr></tbody></table><p><strong>CI:</strong> cache the artifacts root&#39;s <code>builds/</code> dir (default <code>.untestutils/builds</code>; <code>&lt;root&gt;/sessions/&lt;session&gt;/builds</code> with a session; not <code>run/</code>) when inputs are stable; use <code>prewarm</code>; always tear down.</p><h2 id="imports" tabindex="-1">Imports <a class="header-anchor" href="#imports" aria-label="Permalink to &quot;Imports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Import</th><th>Use in</th></tr></thead><tbody><tr><td><code>untestutils</code></td><td><code>defineRecipes</code>, drivers</td></tr><tr><td><code>untestutils/vitest/plugin</code></td><td>Vitest <strong>config</strong> only</td></tr><tr><td><code>untestutils/vitest</code></td><td>Specs</td></tr><tr><td><code>untestutils/playwright</code></td><td>Playwright config + specs</td></tr><tr><td><code>untestutils/nuxt</code></td><td><code>nuxt({ run })</code></td></tr><tr><td><code>untestutils/utils</code></td><td>Cookies, SEO, poll, …</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/untestutils/guide/drivers">Drivers</a></li><li><a href="/untestutils/guide/vitest">Vitest</a></li><li><a href="/untestutils/api/core">API: Core</a></li></ul>',17))])}const T=a(p,[["render",g]]);export{v as __pageData,T as default};
